SELECT CASE WHEN s.rating >= 3.9 THEN 'high' WHEN s.rating >= 2.2 THEN 'mid' ELSE 'low' END AS rating_bucket, MAX(p.launch_date) AS last_launch_date FROM products p JOIN suppliers s ON p.supplier_id = s.id WHERE s.city = 'Berlin' GROUP BY CASE WHEN s.rating >= 3.9 THEN 'high' WHEN s.rating >= 2.2 THEN 'mid' ELSE 'low' END ORDER BY last_launch_date
